 bool choice=std::abs(v.nz)<std::abs(v.ny);if(std::abs(std::abs(v.nx)-1)<1e-6f)choice=!choice;float x=choice?v.ny:v.nz,y=choice?-v.nx:0,z=choice?0:-v.nx;normalize(x,y,z);v.tw=choice?1.f:-1.f;
